-- Fase 86: Business Continuity Management and Disaster Recovery Orchestration.
-- This schema governs plans and evidence; it never performs provider failover or production restore directly.
-- quality: allow-nonconcurrent-index reason=new-empty-business-continuity-tables
alter table public.plans add column if not exists business_continuity_enabled boolean not null default false;
alter table public.plans add column if not exists continuity_advanced_failover_enabled boolean not null default false;
alter table public.plans add column if not exists continuity_exercises_enabled boolean not null default false;

create table public.continuity_member_permissions(organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,permissions text[] not null default '{continuity:view}',service_ids uuid[] not null default '{}',active boolean not null default true,updated_by uuid references auth.users(id),updated_at timestamptz not null default now(),primary key(organization_id,user_id));
create table public.continuity_service_profiles(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,service_id uuid not null references public.reliability_services(id) on delete cascade,owner_user_id uuid not null references auth.users(id),criticality text not null check(criticality in('low','medium','high','critical')),minimum_operating_mode text not null default 'manual_degraded',alternate_region_available boolean not null default false,status text not null default 'draft' check(status in('draft','active','retired')),metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,service_id));
create table public.business_impact_assessments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,service_id uuid not null references public.reliability_services(id) on delete cascade,version integer not null check(version>0),financial_impact smallint not null check(financial_impact between 0 and 5),operational_impact smallint not null check(operational_impact between 0 and 5),customer_impact smallint not null check(customer_impact between 0 and 5),regulatory_impact smallint not null check(regulatory_impact between 0 and 5),safety_impact smallint not null check(safety_impact between 0 and 5),impact_score smallint not null,assumptions jsonb not null default '[]',status text not null default 'draft' check(status in('draft','approved','retired')),approved_by uuid references auth.users(id),effective_from timestamptz not null default now(),effective_until timestamptz,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(service_id,version));
create table public.recovery_objectives(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,service_id uuid not null references public.reliability_services(id) on delete cascade,bia_id uuid references public.business_impact_assessments(id),version integer not null check(version>0),mtd_minutes integer not null check(mtd_minutes>=0),rto_minutes integer not null check(rto_minutes>=0),rpo_minutes integer not null check(rpo_minutes>=0),validation_status text not null default 'unknown' check(validation_status in('valid','gap','unknown')),validation_gaps jsonb not null default '[]',status text not null default 'draft' check(status in('draft','active','retired')),effective_from timestamptz not null,effective_until timestamptz,owner_user_id uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(service_id,version),check(rto_minutes<=mtd_minutes),check(effective_until is null or effective_until>effective_from));
create table public.recovery_capabilities(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,service_id uuid not null references public.reliability_services(id) on delete cascade,capability_type text not null check(capability_type in('backup_restore','warm_standby','cold_restore','active_passive','shadow_rebuild','manual_degraded','provider_failover')),provider_ref text,alternate_region_ref text,estimated_rto_minutes integer check(estimated_rto_minutes is null or estimated_rto_minutes>=0),minimum_rpo_minutes integer check(minimum_rpo_minutes is null or minimum_rpo_minutes>=0),readiness_status text not null default 'unknown' check(readiness_status in('ready','partial','not_ready','unknown')),last_validated_at timestamptz,evidence_ref text,status text not null default 'active',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.continuity_plans(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,service_id uuid not null references public.reliability_services(id) on delete cascade,name text not null,version integer not null check(version>0),objective_id uuid references public.recovery_objectives(id),owner_user_id uuid not null references auth.users(id),status text not null default 'draft' check(status in('draft','published','retired')),activation_criteria jsonb not null default '[]',communication_plan jsonb not null default '{}',effective_from timestamptz not null default now(),effective_until timestamptz,published_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(service_id,version));
create table public.continuity_plan_steps(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,plan_id uuid not null references public.continuity_plans(id) on delete cascade,sequence integer not null check(sequence>0),name text not null,instructions text not null,role_key text not null,runbook_ref text,validation_required boolean not null default true,requires_action_engine boolean not null default false,estimated_minutes integer check(estimated_minutes is null or estimated_minutes>=0),created_at timestamptz not null default now(),unique(plan_id,sequence));
create table public.recovery_dependencies(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,service_id uuid not null references public.reliability_services(id) on delete cascade,dependency_service_id uuid references public.reliability_services(id) on delete cascade,provider_ref text,dependency_type text not null check(dependency_type in('hard','soft','degraded_mode','asynchronous','optional')),recovery_priority integer not null default 100,minimum_mode text,created_at timestamptz not null default now(),check(dependency_service_id is not null or provider_ref is not null),check(dependency_service_id is null or dependency_service_id<>service_id));
create table public.failover_strategies(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,service_id uuid not null references public.reliability_services(id) on delete cascade,strategy text not null check(strategy in('warm_standby','cold_restore','active_passive','shadow_rebuild','manual_degraded')),source_environment text not null,target_environment text not null,adapter_ref text,preconditions jsonb not null default '[]',validation_checks jsonb not null default '[]',failback_checks jsonb not null default '[]',status text not null default 'draft',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.recovery_restore_jobs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,service_id uuid not null references public.reliability_services(id),backup_run_id uuid references public.backup_runs(id),restore_test_run_id uuid references public.restore_test_runs(id),environment text not null check(environment in('sandbox','staging','production')),action_request_ref text,status text not null check(status in('requested','approved','running','passed','failed','cancelled')),started_at timestamptz,completed_at timestamptz,error_summary text,requested_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.restore_validation_results(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,restore_job_id uuid not null references public.recovery_restore_jobs(id) on delete cascade,validation_type text not null check(validation_type in('integrity','application','security','data_reconciliation','performance','business_process')),checks jsonb not null default '[]',status text not null check(status in('passed','failed','partial','unknown')),evidence_ref text,validated_by uuid references auth.users(id),validated_at timestamptz not null default now(),created_at timestamptz not null default now());
create table public.continuity_exercises(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,plan_id uuid references public.continuity_plans(id),exercise_type text not null check(exercise_type in('tabletop','restore_test','failover_simulation','communication_drill')),environment text not null check(environment in('sandbox','staging')),scheduled_at timestamptz not null,started_at timestamptz,completed_at timestamptz,status text not null default 'planned' check(status in('planned','running','completed','cancelled')),scenario jsonb not null default '{}',facilitator_id uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.continuity_exercise_findings(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,exercise_id uuid not null references public.continuity_exercises(id) on delete cascade,severity text not null check(severity in('low','medium','high','critical')),description text not null,owner_user_id uuid not null references auth.users(id),due_at timestamptz not null,status text not null default 'open' check(status in('open','in_progress','resolved','accepted')),action_ref text,created_at timestamptz not null default now());
create table public.continuity_evidence(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,service_id uuid references public.reliability_services(id),evidence_type text not null,source_ref text not null,observed_at timestamptz not null,valid_until timestamptz,quality text not null check(quality in('complete','partial','stale','missing','invalid')),metadata_redacted jsonb not null default '{}',created_at timestamptz not null default now());
create table public.continuity_risks(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,service_id uuid references public.reliability_services(id),title text not null,likelihood smallint not null check(likelihood between 1 and 5),impact smallint not null check(impact between 1 and 5),score smallint not null,mitigation text,owner_user_id uuid not null references auth.users(id),status text not null default 'open' check(status in('open','mitigating','accepted','closed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.continuity_activations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,plan_id uuid not null references public.continuity_plans(id),incident_id uuid references public.operational_incidents(id),status text not null default 'active' check(status in('active','recovering','validating','monitoring','completed','cancelled')),activated_by uuid not null references auth.users(id),activation_reason text not null,started_at timestamptz not null default now(),recovered_at timestamptz,measured_rto_minutes numeric,measured_rpo_minutes numeric,created_at timestamptz not null default now());
create table public.continuity_activation_steps(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,activation_id uuid not null references public.continuity_activations(id) on delete cascade,plan_step_id uuid not null references public.continuity_plan_steps(id),status text not null default 'pending' check(status in('pending','running','blocked','completed','skipped')),validation_status text not null default 'unknown' check(validation_status in('unknown','passed','failed')),sequence_override_reason text,started_at timestamptz,completed_at timestamptz,executed_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(activation_id,plan_step_id));
create table public.continuity_reconciliation_runs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,activation_id uuid not null references public.continuity_activations(id),checks jsonb not null default '[]',status text not null check(status in('running','passed','failed','partial')),signoff_by uuid references auth.users(id),completed_at timestamptz,created_at timestamptz not null default now());
create table public.store_continuity_profiles(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,offline_pack_status text not null default 'unknown',minimum_operations jsonb not null default '[]',contacts jsonb not null default '[]',last_pack_generated_at timestamptz,created_at timestamptz not null default now(),unique(organization_id,store_id));
create table public.provider_continuity_profiles(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,provider_key text not null,services text[] not null default '{}',fallback_provider_ref text,manual_mode text,readiness_status text not null default 'unknown',last_validated_at timestamptz,created_at timestamptz not null default now(),unique(organization_id,provider_key));
create table public.continuity_audit_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,actor_id uuid references auth.users(id),event_type text not null,entity_type text not null,entity_id uuid,reason text,before_state_redacted jsonb,after_state_redacted jsonb,correlation_id uuid not null default gen_random_uuid(),created_at timestamptz not null default now());

create unique index continuity_one_active_activation_per_incident on public.continuity_activations(organization_id,incident_id) where incident_id is not null and status in('active','recovering','validating','monitoring');
create index continuity_profiles_org_idx on public.continuity_service_profiles(organization_id,criticality,status);
create index recovery_objectives_org_idx on public.recovery_objectives(organization_id,service_id,effective_from desc);
create index continuity_plans_org_idx on public.continuity_plans(organization_id,service_id,status);
create index restore_jobs_org_idx on public.recovery_restore_jobs(organization_id,status,created_at desc);
create index continuity_evidence_org_idx on public.continuity_evidence(organization_id,observed_at desc);
create index continuity_activations_org_idx on public.continuity_activations(organization_id,status,started_at desc);
create index continuity_audit_org_idx on public.continuity_audit_events(organization_id,created_at desc);

