('business_continuity','Continuidade de Negócios','BIA, objetivos, planos, validações, exercícios, riscos e recuperações.','hybrid',array['continuity_plan_coverage','recovery_objective_coverage','restore_validation_rate','rto_compliance_rate','rpo_compliance_rate','active_recovery_count'],array['date','store','service','criticality','readiness','strategy'],array['period','store','service','criticality','status'],array['day','week','month'],array['reports:view','continuity:view'],'hybrid','restricted','{"evidence":"deny_without_permission","contacts":"redact","secrets":"never_export"}') on conflict(id) do update set updated_at=now();

