('continuity_plan_coverage','Cobertura de planos de continuidade','Serviços críticos com plano publicado.','critical_services_with_published_plan / critical_services','continuity_readiness_summary','serviço','Operações','5m','ratio','calculation',false,array['date','store','service','criticality']),
('restore_validation_rate','Cobertura de restore validado','Serviços com restore validado e evidência vigente.','services_with_valid_restore / services_requiring_restore','restore_validation_results','serviço','Operações','5m','ratio','calculation',true,array['date','store','service','criticality']),
('rto_compliance_rate','Compliance de RTO medido','Recuperações concluídas dentro do RTO versionado.','recoveries_meeting_rto / measured_recoveries','continuity_activations','recuperação','Operações','hourly','ratio','calculation',true,array['date','store','service','criticality']),
('rpo_compliance_rate','Compliance de RPO medido','Recuperações concluídas dentro do RPO versionado.','recoveries_meeting_rpo / measured_recoveries','continuity_activations','recuperação','Operações','hourly','ratio','calculation',true,array['date','store','service','criticality']) on conflict(metric_key) do nothing;

do $$ declare t text; begin foreach t in array array['continuity_member_permissions','continuity_service_profiles','business_impact_assessments','recovery_objectives','recovery_capabilities','continuity_plans','continuity_plan_steps','recovery_dependencies','failover_strategies','recovery_restore_jobs','restore_validation_results','continuity_exercises','continuity_exercise_findings','continuity_evidence','continuity_risks','continuity_activations','continuity_activation_steps','continuity_reconciliation_runs','store_continuity_profiles','provider_continuity_profiles','continuity_audit_events'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on table public.%I from public,anon,authenticated',t);execute format('grant all on table public.%I to service_role',t);execute format('create policy %I on public.%I for all to service_role using (true) with check (true)','service_role_only_'||t,t);end loop;end $$;

create or replace view public.continuity_readiness_summary with (security_invoker=true) as select p.organization_id,p.service_id,p.criticality,coalesce(o.validation_status,'unknown') objective_status,coalesce(c.readiness_status,'unknown') capability_status,max(e.observed_at) evidence_as_of,count(distinct r.id) filter(where r.status<>'closed') open_risks from public.continuity_service_profiles p left join public.recovery_objectives o on o.organization_id=p.organization_id and o.service_id=p.service_id and o.status='active' left join public.recovery_capabilities c on c.organization_id=p.organization_id and c.service_id=p.service_id left join public.continuity_evidence e on e.organization_id=p.organization_id and e.service_id=p.service_id left join public.continuity_risks r on r.organization_id=p.organization_id and r.service_id=p.service_id group by p.organization_id,p.service_id,p.criticality,o.validation_status,c.readiness_status;
revoke all on public.continuity_readiness_summary from public,anon,authenticated;
grant select on public.continuity_readiness_summary to service_role;

